383	    static func arrayPayload(from value: JSONValue, preferredKeys: [String]) -> [JSONValue] {
384	        if let array = value.arrayValue {
385	            return array
386	        }
387	
388	        guard let object = value.objectValue else {
389	            return []
390	        }
391	
392	        for key in preferredKeys {
393	            if let array = object[key]?.arrayValue {
394	                return array
395	            }
396	        }
397	
398	        return []
399	    }
