401	    static func hasVehicleStatus(_ value: JSONValue?) -> Bool {
402	        let root = value?.objectValue ?? [:]
403	        let object = payloadObject(root, preferredKeys: ["status", "vehicle_status", "vehicleStatus", "data"])
404	        guard !object.isEmpty else { return false }
405	        return firstDouble(
406	            ["dump_energy", "dumpEnergy", "precise_estimate_mileage", "preciseEstimateMileage", "estimate_mileage", "estimateMileage", "pwr", "charging", "lock_status", "lockStatus"],
407	            in: [object, root]
408	        ) != nil || firstObject(["loc", "locationInfo"], in: object) != nil
409	    }
410	
411	    static func hasBatteryData(_ value: JSONValue?) -> Bool {
412	        let root = value?.objectValue ?? [:]
413	        let object = payloadObject(root, preferredKeys: ["battery", "batteryInfo", "battery_info", "data"])
414	        guard !object.isEmpty else { return false }
415	        return firstDouble(
416	            ["electricity", "dump_energy", "dumpEnergy", "battery_voltage", "batteryVoltage", "bms_volt", "bmsVolt", "bat_temp", "batt_temp", "charging_power", "chargingPower"],
417	            in: [object, root]
418	        ) != nil || firstArrayObject(["battery_list", "batteryList", "batteries"], in: object) != nil
419	    }
