421	    static func vehicleInfo(from value: JSONValue) -> NinebotVehicleInfo? {
422	        guard let object = value.objectValue else { return nil }
423	        guard let sn = firstString(["wnumber", "sn"], in: object), !sn.isEmpty else {
424	            return nil
425	        }
426	
427	        var model = firstString(["vehicle_name_en", "vehicle_name", "model", "vehicleModel"], in: object) ?? sn
428	        if let vehicleType = object["vehicle_type"]?.stringValue, !vehicleType.isEmpty {
429	            model = "\(model) (\(vehicleType))"
430	        }
431	
432	        return NinebotVehicleInfo(
433	            sn: sn,
434	            name: firstString(["device_name", "deviceName", "ble_name"], in: object) ?? sn,
435	            model: model,
436	            imageURLString: firstString(["v6_light_img_url", "img_url", "img"], in: object),
437	            raw: object
438	        )
439	    }
