441	    static func vehicleInfo(_ vehicle: NinebotVehicleInfo, addingImageFrom status: JSONValue?, battery: JSONValue?) -> NinebotVehicleInfo {
442	        guard vehicle.imageURLString?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty != false else {
443	            return vehicle
444	        }
445	
446	        let statusRoot = status?.objectValue ?? [:]
447	        let batteryRoot = battery?.objectValue ?? [:]
448	        let statusObject = payloadObject(statusRoot, preferredKeys: ["status", "vehicle_status", "vehicleStatus", "data"])
449	        let statusVehicleObject = firstObject(["vehicle", "vehicleInfo", "vehicle_info"], in: statusRoot) ?? [:]
450	        let batteryObject = payloadObject(batteryRoot, preferredKeys: ["battery", "batteryInfo", "battery_info", "data"])
451	        guard let imageURLString = firstString(
452	            ["v6_light_img_url", "v6LightImgUrl", "img_url", "imgUrl", "img", "image_url", "imageUrl"],
453	            in: [statusObject, statusVehicleObject, statusRoot, batteryObject, batteryRoot]
454	        ) else {
455	            return vehicle
456	        }
457	
458	        var resolved = vehicle
459	        resolved.imageURLString = imageURLString
460	        return resolved
461	    }
