537	            month: firstString(["month"], in: object) ?? fallbackMonth,
538	            page: object["page"]?.intValue ?? 1,
539	            pageSize: object["page_size"]?.intValue ?? object["pageSize"]?.intValue ?? records.count,
540	            total: object["total"]?.intValue ?? records.count,
541	            hasMore: object["has_more"]?.boolValue ?? object["hasMore"]?.boolValue ?? false,
542	            records: records,
