547	    static func vehicleState(
548	        status: JSONValue?,
549	        travel: JSONValue?,
550	        battery: JSONValue? = nil,
551	        prediction: NinebotServerPrediction? = nil,
552	        updatedAt: Date
553	    ) -> NinebotVehicleState {
554	        let statusRoot = status?.objectValue ?? [:]
555	        let statusObject = payloadObject(statusRoot, preferredKeys: ["status", "vehicle_status", "vehicleStatus", "data"])
556	        let travelObject = travel?.objectValue ?? [:]
557	        let batteryRoot = battery?.objectValue ?? [:]
558	        let batteryPayloadObject = payloadObject(batteryRoot, preferredKeys: ["battery", "batteryInfo", "battery_info", "data"])
559	        let statusBatteryObject = firstObject(["battery", "batteryInfo", "battery_info", "bms", "bmsInfo", "bms_info"], in: statusObject)
560	            ?? firstObject(["battery", "batteryInfo", "battery_info", "bms", "bmsInfo", "bms_info"], in: statusRoot)
561	            ?? [:]
562	        let batteryListObject = firstArrayObject(["battery_list", "batteryList", "batteries"], in: batteryPayloadObject)
563	            ?? firstArrayObject(["battery_list", "batteryList", "batteries"], in: batteryRoot)
564	            ?? [:]
565	        let batteryMainObject = firstObject(["battery_main", "batteryMain"], in: batteryPayloadObject)
566	            ?? firstObject(["battery_main", "batteryMain"], in: batteryRoot)
567	            ?? [:]
