1027	    static func structuredChinaDateValue(_ text: String) -> Date? {
1028	        let digitsOnly = text.allSatisfy(\.isNumber)
1029	        guard digitsOnly else { return nil }
1030	
1031	        let format: String
1032	        switch text.count {
1033	        case 14:
1034	            format = "yyyyMMddHHmmss"
1035	        case 12:
1036	            format = "yyyyMMddHHmm"
1037	        case 8:
1038	            format = "yyyyMMdd"
1039	        default:
1040	            return nil
1041	        }
1042	
1043	        return chinaDateFormatter(format: format).date(from: text)
1044	    }
