1046	    static func epochDateValue(_ number: Double) -> Date? {
1047	        if number > 1_000_000_000_000 {
1048	            return Date(timeIntervalSince1970: number / 1000)
1049	        }
1050	        if number > 1_000_000_000 {
1051	            return Date(timeIntervalSince1970: number)
1052	        }
1053	        return nil
1054	    }
