1056	    static func firstDurationValue(_ keys: [String], in object: [String: JSONValue]) -> Double? {
1057	        for key in keys {
1058	            guard let value = object[key] else { continue }
1059	            if let clockDuration = clockDurationMinutes(value) {
1060	                return clockDuration
1061	            }
1062	            if let numericDuration = value.doubleValue, numericDuration > 0 {
1063	                return numericDuration
1064	            }
1065	        }
1066	        return nil
1067	    }
1068	
1069	    static func clockDurationMinutes(_ value: JSONValue) -> Double? {
1070	        guard let string = value.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines),
1071	              string.contains(":") else {
1072	            return nil
1073	        }
1074	
1075	        let parts = string.split(separator: ":").compactMap { Double($0) }
1076	        guard parts.count == 2 || parts.count == 3 else { return nil }
1077	
1078	        if parts.count == 2 {
1079	            return parts[0] + parts[1] / 60
1080	        }
1081	        return parts[0] * 60 + parts[1] + parts[2] / 60
1082	    }
1083	
1084	    static func durationMinutes(startedAt: Date?, endedAt: Date?) -> Double? {
1085	        guard let startedAt, let endedAt else { return nil }
1086	        let minutes = endedAt.timeIntervalSince(startedAt) / 60
1087	        guard minutes > 0, minutes <= 48 * 60 else { return nil }
1088	        return minutes
1089	    }
1090	
1091	    static func ambiguousDurationMinutes(_ value: Double, derived: Double?) -> Double {
1092	        guard let derived else {
1093	            return value > 300 ? value / 60 : value
1094	        }
1095	
1096	        let minuteCandidate = value
1097	        let secondCandidate = value / 60
1098	        return abs(secondCandidate - derived) < abs(minuteCandidate - derived)
1099	            ? secondCandidate
1100	            : minuteCandidate
1101	    }
1102	
1103	    static func saneDuration(_ value: Double, fallback: Double?) -> Double? {
1104	        guard value > 0, value <= 48 * 60 else {
1105	            return fallback
1106	        }
1107	        return value
1108	    }
1109	}
